create temporary table workflow_snapshot_state(completeness_digest text,conversation_digest text) on commit drop;
insert into pg_temp.workflow_snapshot_state select
  (select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) from pg_temp.workflow_snapshot_predecessor),
  (select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) from pg_temp.workflow_snapshot_conversation);
update pg_temp.workflow_snapshot_predecessor p set definition=c.definition
  from pg_temp.workflow_snapshot_conversation c where p.table_name=c.table_name;
create temporary table workflow_snapshot_rows(id text primary key,body_text text,row_version bigint,original_columns jsonb) on commit drop;
create temporary table workflow_snapshot_modes(table_oid oid,trigger_name text,enabled "char",primary key(table_oid,trigger_name)) on commit drop;

-- Additive message-proof parity with lib/packs/shared.ts. Existing 040001 body
-- guards remain installed; this guard fills only their optional evidence/sources gap.
create or replace function nexus_private.workflow_chat_metric_number(value jsonb,require_nonnegative boolean,require_integral boolean,allow_null boolean)
returns boolean language plpgsql immutable set search_path='' as $$
declare number_value double precision;
begin
  if value='null'::jsonb then return allow_null; end if;
  if jsonb_typeof(value) is distinct from 'number' then return false; end if;
  -- Zod validates JavaScript numbers. Round JSONB numerics through IEEE float8;
  -- JSON numbers that underflow to zero remain valid zero, as with JSON.parse.
  begin
    number_value:=(value #>> '{}')::double precision;
  exception when numeric_value_out_of_range then
    if abs((value #>> '{}')::numeric)<1 then number_value:=0; else return false; end if;
  end;
  if number_value not between '-1.7976931348623157e308'::double precision and '1.7976931348623157e308'::double precision
    or (require_nonnegative and number_value<0)
    or (require_integral and (trunc(number_value)<>number_value or abs(number_value)>9007199254740991)) then return false; end if;
  return true;
exception when invalid_text_representation or numeric_value_out_of_range then return false;
end $$;

create or replace function nexus_private.workflow_chat_source(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
begin
  if jsonb_typeof(value) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(value))<>6
    or not value ?& array['id','system','observedAt','retrievedAt','freshness','detail']
    or jsonb_typeof(value->'id') is distinct from 'string' or length(value->>'id')<1
    or jsonb_typeof(value->'system') is distinct from 'string' or length(value->>'system')<1
    or jsonb_typeof(value->'observedAt') is distinct from 'string'
    or not nexus_private.workflow_chat_instant(value->'retrievedAt')
    or jsonb_typeof(value->'freshness') is distinct from 'string' or value->>'freshness' not in('fresh','stale','misaligned','missing')
    or jsonb_typeof(value->'detail') is distinct from 'string' or nexus_private.workflow_utf16_length(value->>'detail') not between 1 and 500 then return false; end if;
  if value->>'observedAt'='' then return value->>'freshness'='missing'; end if;
  return nexus_private.workflow_chat_instant(value->'observedAt');
end $$;

create or replace function nexus_private.workflow_chat_sources(value jsonb,maximum integer) returns boolean
language plpgsql immutable set search_path='' as $$
declare item jsonb;
begin
  if jsonb_typeof(value) is distinct from 'array' then return false; end if;
  if jsonb_array_length(value)>maximum then return false; end if;
  for item in select element from jsonb_array_elements(value) element loop
    if not nexus_private.workflow_chat_source(item) then return false; end if;
  end loop;
  return true;
end $$;

create or replace function nexus_private.workflow_chat_evidence_date(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
begin
  if jsonb_typeof(value) is distinct from 'string' then return false; end if;
  if value #>> '{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false; end if;
  return nexus_private.workflow_chat_instant(to_jsonb((value #>> '{}')||'T00:00:00Z'));
end $$;

create or replace function nexus_private.workflow_chat_incident(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
begin
  if jsonb_typeof(value) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(value))<>9
    or not value ?& array['id','branchId','date','title','kind','status','startedAt','endedAt','updatedAt']
    or jsonb_typeof(value->'id') is distinct from 'string' or length(value->>'id')<1
    or jsonb_typeof(value->'branchId') is distinct from 'string' or length(value->>'branchId')<1
    or jsonb_typeof(value->'title') is distinct from 'string' or length(value->>'title')<1
    or not nexus_private.workflow_chat_evidence_date(value->'date')
    or jsonb_typeof(value->'kind') is distinct from 'string' or value->>'kind' not in('payment','stock','operations')
    or jsonb_typeof(value->'status') is distinct from 'string' or value->>'status' not in('open','resolved')
    or not nexus_private.workflow_chat_instant(value->'startedAt')
    or not nexus_private.workflow_chat_instant(value->'updatedAt') then return false; end if;
  return value->'endedAt'='null'::jsonb or nexus_private.workflow_chat_instant(value->'endedAt');
end $$;

create or replace function nexus_private.workflow_chat_totals(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
begin
  if jsonb_typeof(value) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(value))<>4 or not value ?& array['netSales','target','gap','achievement'] then return false; end if;
  return nexus_private.workflow_chat_metric_number(value->'netSales',false,false,false)
    and nexus_private.workflow_chat_metric_number(value->'target',true,false,false)
    and nexus_private.workflow_chat_metric_number(value->'gap',false,false,false)
    and nexus_private.workflow_chat_metric_number(value->'achievement',true,false,true);
end $$;

create or replace function nexus_private.workflow_chat_branch_metric(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare field text; item jsonb;
begin
  if jsonb_typeof(value) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(value))<>13
    or not value ?& array['branchId','branchName','region','netSales','target','gap','achievement','stockIssues','incidentCount','staffingPlanned','staffingActual','incidents','sourceIds'] then return false; end if;
  foreach field in array array['branchId','branchName','region'] loop
    if jsonb_typeof(value->field) is distinct from 'string' or length(value->>field)<1 then return false; end if;
  end loop;
  if not nexus_private.workflow_chat_metric_number(value->'netSales',false,false,false)
    or not nexus_private.workflow_chat_metric_number(value->'target',true,false,false)
    or not nexus_private.workflow_chat_metric_number(value->'gap',false,false,false)
    or not nexus_private.workflow_chat_metric_number(value->'achievement',true,false,true) then return false; end if;
  foreach field in array array['stockIssues','incidentCount','staffingPlanned','staffingActual'] loop
    if not nexus_private.workflow_chat_metric_number(value->field,true,true,false) then return false; end if;
  end loop;
  if jsonb_typeof(value->'incidents') is distinct from 'array' or jsonb_typeof(value->'sourceIds') is distinct from 'array' then return false; end if;
  if jsonb_array_length(value->'incidents')>120 or jsonb_array_length(value->'sourceIds')>100 then return false; end if;
  for item in select element from jsonb_array_elements(value->'incidents') element loop
    if not nexus_private.workflow_chat_incident(item) then return false; end if;
  end loop;
  for item in select element from jsonb_array_elements(value->'sourceIds') element loop
    if jsonb_typeof(item) is distinct from 'string' or length(item #>> '{}')<1 then return false; end if;
  end loop;
  return true;
end $$;

create or replace function nexus_private.workflow_chat_evidence(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare item jsonb;
begin
  if jsonb_typeof(value) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(value))<>7 or not value ?& array['scope','asOf','version','branches','totals','sources','warnings']
    or jsonb_typeof(value->'scope') is distinct from 'object' or not nexus_private.workflow_chat_scope(value->'scope')
    or not nexus_private.workflow_chat_instant(value->'asOf')
    or jsonb_typeof(value->'version') is distinct from 'string' or length(value->>'version')<1
    or jsonb_typeof(value->'branches') is distinct from 'array' or jsonb_typeof(value->'warnings') is distinct from 'array'
    or not nexus_private.workflow_chat_totals(value->'totals') or not nexus_private.workflow_chat_sources(value->'sources',100) then return false; end if;
  if jsonb_array_length(value->'branches')>12 or jsonb_array_length(value->'warnings')>50 then return false; end if;
  for item in select element from jsonb_array_elements(value->'branches') element loop
    if not nexus_private.workflow_chat_branch_metric(item) then return false; end if;
  end loop;
  for item in select element from jsonb_array_elements(value->'warnings') element loop
    if jsonb_typeof(item) is distinct from 'string' or nexus_private.workflow_utf16_length(item #>> '{}')>500 then return false; end if;
  end loop;
  return true;
end $$;

create or replace function nexus_private.workflow_chat_proof_valid(body jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
begin
  if jsonb_typeof(body) is distinct from 'object' then return false; end if;
  if body ? 'evidence' and not nexus_private.workflow_chat_evidence(body->'evidence') then return false; end if;
  if body ? 'sources' and not nexus_private.workflow_chat_sources(body->'sources',500) then return false; end if;
  return true;
end $$;

create or replace function nexus_private.workflow_chat_proof_guard() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if not nexus_private.workflow_chat_proof_valid(new.payload) then
    raise exception 'Invalid persisted conversation evidence or sources' using errcode='23514';
  end if;
  return new;
end $$;

do $forward$
declare item record; f jsonb; c jsonb; d jsonb; v jsonb; saved record;
  step_digest text; installed_digest text; saved_meta text; saved_ledger text;
  colname text; marker text; constraint_name text; existed boolean; changed boolean;
  source_keys smallint[]; target_keys smallint[]; reference_count integer;
begin
  select definition into strict d from pg_temp.workflow_snapshot_manifest where table_name='review_snapshot_targets';
  select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) into step_digest from pg_temp.workflow_snapshot_manifest;
  -- Lock metadata first, then every affected FK source/target. No concurrent direct write
  -- can invalidate projection backfill or the revision/ledger preservation proof.
  for item in
    select t.oid,t.relowner,n.nspname,t.relname from pg_catalog.pg_class t join pg_catalog.pg_namespace n on n.oid=t.relnamespace
    where (n.nspname='public' and t.relname in('appmeta','review_snapshot_targets','directory_identities','responsibilities','action_executions','conversation_messages'))
      or (n.nspname='nexus_private' and t.relname in('workflow_manifest','workflow_projection_migrations'))
    order by case when t.relname='appmeta' then 0 else 1 end,n.nspname,t.relname
  loop
    if not pg_catalog.pg_has_role(current_user,item.relowner,'USAGE') and not (select rolsuper from pg_catalog.pg_roles where rolname=current_user) then
      raise exception 'Workflow snapshot proof requires table ownership' using errcode='42501';
    end if;
    execute format('lock table %I.%I in access exclusive mode',item.nspname,item.relname);
  end loop;
  if (select definition_digest from nexus_private.workflow_projection_migrations where id='202610030002_workflow_projection_completeness')
      is distinct from (select completeness_digest from pg_temp.workflow_snapshot_state)
    or (select definition_digest from nexus_private.workflow_projection_migrations where id='202610040001_workflow_conversation_persistence')
      is distinct from (select conversation_digest from pg_temp.workflow_snapshot_state) then
    raise exception 'Workflow snapshot proof requires frozen predecessor ledgers' using errcode='23514';
  end if;
  select definition_digest into installed_digest from nexus_private.workflow_projection_migrations where id='202610040002_workflow_snapshot_proof_references';
  if installed_digest is not null and installed_digest<>step_digest then raise exception 'Workflow snapshot proof manifest changed without a new schema version' using errcode='23514'; end if;
  if exists(select 1 from pg_temp.workflow_snapshot_predecessor p full join nexus_private.workflow_manifest m using(table_name)
    left join pg_temp.workflow_snapshot_manifest s using(table_name)
    where p.table_name is null or m.table_name is null
      or m.definition is distinct from case when installed_digest is not null and s.table_name is not null then s.definition else p.definition end) then
    raise exception 'Workflow snapshot proof preceding manifest does not match its ledger' using errcode='23514';
  end if;
  if exists(select 1 from (values('workflow_guard'),('nexus_revision')) required(trigger_name)
    left join pg_catalog.pg_trigger t on t.tgrelid='public.review_snapshot_targets'::regclass and t.tgname=required.trigger_name
    where t.oid is null or t.tgenabled not in('O','A')) then raise exception 'Workflow snapshot proof requires active preceding guards' using errcode='23514'; end if;
  if (select workflow_adapter_write from public.appmeta where singleton=1)<>0 then raise exception 'Workflow snapshot proof found an active adapter write' using errcode='23514'; end if;
  select to_jsonb(a)::text into strict saved_meta from public.appmeta a where singleton=1;
  select coalesce(string_agg(id||':'||definition_digest,E'\n' order by id),'') into saved_ledger from nexus_private.workflow_projection_migrations;
  -- Existing rows are validated before the new guard is adopted. Any malformed
  -- historical proof rolls the entire forward transaction back without changing it.
  if exists(select 1 from public.conversation_messages where not nexus_private.workflow_chat_proof_valid(payload)) then
    raise exception 'Workflow snapshot proof contains incompatible historical conversation proof' using errcode='23514';
  end if;
  insert into pg_temp.workflow_snapshot_rows select id,body::text,row_version,to_jsonb(t) from public.review_snapshot_targets t;
  insert into pg_temp.workflow_snapshot_modes
    select tgrelid,tgname,tgenabled from pg_catalog.pg_trigger where tgrelid='public.review_snapshot_targets'::regclass
      and tgname in('workflow_guard','workflow_children','nexus_revision');
  if installed_digest is null then
    if exists(select 1 from pg_catalog.pg_trigger where tgrelid='public.review_snapshot_targets'::regclass
      and not tgisinternal and tgenabled<>'D' and tgname not in('workflow_guard','workflow_children','nexus_revision')) then
      raise exception 'Workflow snapshot proof cannot suspend an unknown application trigger' using errcode='23514';
    end if;
    for item in select * from pg_temp.workflow_snapshot_modes loop
      execute format('alter table %s disable trigger %I',item.table_oid::regclass,item.trigger_name);
    end loop;
  end if;
  -- The loop interleaves column DDL with backfills. Validate native FK events
  -- immediately so an UPDATE cannot leave pending checks before the next ALTER.
  -- Internal FK triggers stay enabled throughout this atomic migration.
  set constraints all immediate;
  for c in select value from jsonb_array_elements(d->'columns') where value->>'column' in('directory_identity_id','responsibility_id','action_execution_id') loop
    colname:=c->>'column';
    select exists(select 1 from pg_catalog.pg_attribute where attrelid='public.review_snapshot_targets'::regclass and attname=colname and not attisdropped) into existed;
    if existed then
      if exists(select 1 from pg_catalog.pg_attribute where attrelid='public.review_snapshot_targets'::regclass and attname=colname
        and (atttypid<>'text'::regtype or attnotnull or attgenerated<>'' or atthasdef)) then raise exception 'Workflow snapshot proof native reference has an incompatible definition' using errcode='23514'; end if;
      execute format('select exists(select 1 from public.review_snapshot_targets where %I is distinct from (nexus_private.workflow_value(body,$1) #>> ''{}''))',colname) into changed using c;
      if changed then raise exception 'Workflow snapshot proof contains contradictory native reference' using errcode='23514'; end if;
    elsif installed_digest is not null then raise exception 'Workflow snapshot proof installed column is missing' using errcode='23514';
    else
      execute format('alter table public.review_snapshot_targets add column %I text',colname);
      execute format('update public.review_snapshot_targets set %I=nexus_private.workflow_value(body,$1) #>> ''{}''',colname) using c;
    end if;
  end loop;
  marker:='action_execution_contract_version';
  if not exists(select 1 from pg_catalog.pg_attribute where attrelid='public.review_snapshot_targets'::regclass and attname=marker and not attisdropped) then
    if installed_digest is not null then raise exception 'Workflow snapshot proof execution marker is missing' using errcode='23514'; end if;
    alter table public.review_snapshot_targets add column action_execution_contract_version integer
      generated always as (case when action_execution_id is not null then 2 else null end) stored;
  end if;
  if not exists(select 1 from pg_catalog.pg_attribute a join pg_catalog.pg_attrdef x on x.adrelid=a.attrelid and x.adnum=a.attnum
    where a.attrelid='public.review_snapshot_targets'::regclass and a.attname=marker and a.atttypid='integer'::regtype
      and a.attgenerated='s' and not a.attnotnull
      and lower(regexp_replace(pg_catalog.pg_get_expr(x.adbin,x.adrelid),'[()[:space:]]','','g'))='casewhenaction_execution_idisnotnullthen2elsenull::integerend') then
    raise exception 'Workflow snapshot proof execution marker has incompatible provenance' using errcode='23514';
  end if;
  if not exists(select 1 from pg_catalog.pg_index i where i.indrelid='public.action_executions'::regclass
    and i.indexrelid=to_regclass('public.workflow_action_executions_contract_reference_unique') and i.indisunique and i.indisvalid and i.indisready
    and i.indpred is null and i.indexprs is null and i.indnkeyatts=2 and i.indnatts=2
    and (select array_agg(a.attname::text order by k.position) from unnest(i.indkey) with ordinality k(attnum,position)
      join pg_catalog.pg_attribute a on a.attrelid=i.indrelid and a.attnum=k.attnum)=array['id','workflow_contract_version']) then
    raise exception 'Workflow snapshot proof requires the native V2 execution reference key' using errcode='23514';
  end if;
  for f in select value from jsonb_array_elements(d->'foreignKeys') where value->>'column' in('directory_identity_id','responsibility_id','action_execution_id') loop
    colname:=f->>'column'; constraint_name:='wf_review_snapshot_targets_'||colname||'_fk';
    source_keys:=array[(select attnum from pg_catalog.pg_attribute where attrelid='public.review_snapshot_targets'::regclass and attname=colname)];
    target_keys:=array[(select attnum from pg_catalog.pg_attribute where attrelid=format('public.%I',f->>'target')::regclass and attname='id')];
    if not exists(select 1 from pg_catalog.pg_constraint where conrelid='public.review_snapshot_targets'::regclass and conname=constraint_name) then
      if installed_digest is not null then raise exception 'Workflow snapshot proof installed FK is missing' using errcode='23514'; end if;
      execute format('alter table public.review_snapshot_targets add constraint %I foreign key(%I) references public.%I(id) on delete no action deferrable initially deferred',constraint_name,colname,f->>'target');
    end if;
    if not exists(select 1 from pg_catalog.pg_constraint where conrelid='public.review_snapshot_targets'::regclass and conname=constraint_name
      and contype='f' and confrelid=format('public.%I',f->>'target')::regclass and conkey=source_keys and confkey=target_keys
      and confdeltype='a' and confupdtype='a' and condeferrable and condeferred and convalidated) then
      raise exception 'Workflow snapshot proof native FK is incompatible' using errcode='23514';
    end if;
  end loop;
  constraint_name:='wf_review_snapshot_targets_action_execution_id_contract_fk';
  if not exists(select 1 from pg_catalog.pg_constraint where conrelid='public.review_snapshot_targets'::regclass and conname=constraint_name) then
    if installed_digest is not null then raise exception 'Workflow snapshot proof installed contract FK is missing' using errcode='23514'; end if;
    alter table public.review_snapshot_targets add constraint wf_review_snapshot_targets_action_execution_id_contract_fk
      foreign key(action_execution_id,action_execution_contract_version) references public.action_executions(id,workflow_contract_version)
      on delete no action deferrable initially deferred;
  end if;
  source_keys:=array[(select attnum from pg_catalog.pg_attribute where attrelid='public.review_snapshot_targets'::regclass and attname='action_execution_id'),
    (select attnum from pg_catalog.pg_attribute where attrelid='public.review_snapshot_targets'::regclass and attname='action_execution_contract_version')];
  target_keys:=array[(select attnum from pg_catalog.pg_attribute where attrelid='public.action_executions'::regclass and attname='id'),
    (select attnum from pg_catalog.pg_attribute where attrelid='public.action_executions'::regclass and attname='workflow_contract_version')];
  if not exists(select 1 from pg_catalog.pg_constraint where conrelid='public.review_snapshot_targets'::regclass and conname=constraint_name
    and contype='f' and confrelid='public.action_executions'::regclass and conkey=source_keys and confkey=target_keys
    and confdeltype='a' and confupdtype='a' and condeferrable and condeferred and convalidated) then
    raise exception 'Workflow snapshot proof native contract FK is incompatible' using errcode='23514';
  end if;
  -- Validate every explicit body and native projection without rewriting JSON or versions.
  for saved in select * from public.review_snapshot_targets loop
    if jsonb_typeof(saved.body) is distinct from 'object' or saved.body->>'id' is distinct from saved.id
      or saved.body->>'entityType' is distinct from saved.body #>> '{ref,table}'
      or exists(select 1 from jsonb_object_keys(saved.body) k where not (d->'bodyFields') ? k)
      or (saved.body ? 'rowVersion' and saved.body->>'rowVersion' is distinct from saved.row_version::text) then
      raise exception 'Workflow snapshot proof contains incompatible historical body' using errcode='23514';
    end if;
    reference_count:=0;
    for c in select value from jsonb_array_elements(d->'columns') loop
      v:=nexus_private.workflow_value(saved.body,c);
      if (v='null'::jsonb and not (c->>'nullable')::boolean)
        or (v<>'null'::jsonb and ((c->>'type'='text' and jsonb_typeof(v)<>'string')
          or (c->>'type'='integer' and (jsonb_typeof(v)<>'number' or v::text !~ '^[1-9][0-9]*$'))))
        or to_jsonb(saved)->(c->>'column') is distinct from v then
        raise exception 'Workflow snapshot proof contains incompatible historical projection' using errcode='23514';
      end if;
      if c ? 'tagField' and v<>'null'::jsonb then reference_count:=reference_count+1; end if;
    end loop;
    if reference_count<>1 then raise exception 'Workflow snapshot proof requires exactly one tagged reference' using errcode='23514'; end if;
  end loop;
  if installed_digest is null then
    update nexus_private.workflow_manifest m set definition=s.definition from pg_temp.workflow_snapshot_manifest s where m.table_name=s.table_name;
    for item in select * from pg_temp.workflow_snapshot_modes loop
      execute format('alter table %s %s trigger %I',item.table_oid::regclass,
        case item.enabled when 'D' then 'disable' when 'R' then 'enable replica' when 'A' then 'enable always' else 'enable' end,item.trigger_name);
    end loop;
  end if;
  if exists((select id,body::text,row_version from public.review_snapshot_targets except select id,body_text,row_version from pg_temp.workflow_snapshot_rows)
    union all (select id,body_text,row_version from pg_temp.workflow_snapshot_rows except select id,body::text,row_version from public.review_snapshot_targets)) then
    raise exception 'Workflow snapshot proof changed historical bodies or versions' using errcode='23514';
  end if;
  if exists(select 1 from pg_temp.workflow_snapshot_rows s join public.review_snapshot_targets t on t.id=s.id
    cross join lateral jsonb_each(s.original_columns) old_column where to_jsonb(t)->old_column.key is distinct from old_column.value) then
    raise exception 'Workflow snapshot proof changed an existing native projection' using errcode='23514';
  end if;
  if (select to_jsonb(a)::text from public.appmeta a where singleton=1) is distinct from saved_meta
    or (select coalesce(string_agg(id||':'||definition_digest,E'\n' order by id),'') from nexus_private.workflow_projection_migrations) is distinct from saved_ledger
    or exists(select 1 from pg_temp.workflow_snapshot_modes s left join pg_catalog.pg_trigger t on t.tgrelid=s.table_oid and t.tgname=s.trigger_name
      where t.oid is null or t.tgenabled is distinct from s.enabled) then
    raise exception 'Workflow snapshot proof changed application revision, ledger history or trigger modes' using errcode='23514';
  end if;
  if installed_digest is null then
    create trigger workflow_chat_proof_guard before insert or update on public.conversation_messages
      for each row execute function nexus_private.workflow_chat_proof_guard();
  elsif not exists(select 1 from pg_catalog.pg_trigger t where t.tgrelid='public.conversation_messages'::regclass
    and t.tgname='workflow_chat_proof_guard' and t.tgfoid='nexus_private.workflow_chat_proof_guard()'::regprocedure
    and t.tgenabled in('O','A') and not t.tgisinternal and t.tgtype=23 and t.tgnargs=0 and t.tgqual is null) then
    raise exception 'Workflow snapshot proof conversation proof guard is incompatible' using errcode='23514';
  end if;
  if installed_digest is null then insert into nexus_private.workflow_projection_migrations values('202610040002_workflow_snapshot_proof_references',step_digest); end if;
end $forward$;
set constraints all immediate;
revoke all on function nexus_private.workflow_chat_metric_number(jsonb,boolean,boolean,boolean),
  nexus_private.workflow_chat_source(jsonb),nexus_private.workflow_chat_sources(jsonb,integer),
  nexus_private.workflow_chat_evidence_date(jsonb),nexus_private.workflow_chat_incident(jsonb),
  nexus_private.workflow_chat_totals(jsonb),nexus_private.workflow_chat_branch_metric(jsonb),
  nexus_private.workflow_chat_evidence(jsonb),nexus_private.workflow_chat_proof_valid(jsonb),
  nexus_private.workflow_chat_proof_guard() from public,anon,authenticated,service_role;
commit;
